  assert(text.includes('Subtotal: €730.00'));
  assert(text.includes('Discount: -€38.25'));
  assert(text.includes('Total: €691.75'));
});

test('renderInvoiceText: with 100% discount shows zero total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 100 }],
  });

  assert(result.ok);
  const text = renderInvoiceText(result.value);

  assert(text.includes('Subtotal: €475.00'));
  assert(text.includes('Discount: -€475.00'));
  assert(text.includes('Total: €0.00'));
});

