import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice: valid invoice with single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[0].unitPrice, 9500);
  assert.equal(result.value.lines[0].vatRate, 21);
});

test('createInvoice: valid invoice with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  });

  assert(result.ok);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[1].name, 'Logo package');
  assert.equal(result.value.lines[2].name, 'Sticker sheet');
});

test('createInvoice: different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 100 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT exempt
    ],
  });

  assert(result.ok);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('createInvoice: customer not found', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert(!result.ok);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice: invalid date format', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '10-07-2026',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert(!result.ok);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice: invalid date (non-existent)', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert(!result.ok);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice: empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });

  assert(!result.ok);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice: missing lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: undefined,
  });

  assert(!result.ok);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice: qty not a positive integer', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 2.5 }],
  });

  assert(!result.ok);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice: qty is zero', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });

  assert(!result.ok);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice: qty is negative', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });

  assert(!result.ok);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice: unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NONEXISTENT', qty: 1 }],
  });

  assert(!result.ok);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice: does not mutate input', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 5 }];
  const originalLines = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });

  assert.deepEqual(lines, originalLines);
});

test('createInvoice: returns new object, not reference to input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  };

  const result1 = createInvoice(input);
  const result2 = createInvoice(input);

  assert.notStrictEqual(result1.value, result2.value);
  assert.notStrictEqual(result1.value.lines, result2.value.lines);
});

test('lineTotal: calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('lineTotal: handles large quantities', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 100000 }), 100000000);
});

test('lineTotal: returns integer cents', () => {
  const result = lineTotal({ qty: 3, unitPrice: 6500 });
  assert(Number.isInteger(result));
  assert.equal(result, 19500);
});

test('invoiceTotals: single line invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.total, 47500);
});

test('invoiceTotals: multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500 }, // 47500
      { qty: 1, unitPrice: 120000 }, // 120000
      { qty: 100, unitPrice: 50 }, // 5000
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 172500);
  assert.equal(totals.total, 172500);
});

test('invoiceTotals: empty invoice', () => {
  const invoice = { lines: [] };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals: returns integers', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100 },
      { qty: 2, unitPrice: 200 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert(Number.isInteger(totals.subtotal));
  assert(Number.isInteger(totals.total));
});

test('invoiceTotals: with invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 }, // 10 * 9500 = 95000
      { sku: 'DES-HOUR', qty: 5 }, // 5 * 8500 = 42500
    ],
  });

  assert(result.ok);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals: does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };
  const originalInvoice = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepEqual(invoice, originalInvoice);
});

test('addLine: adds a new line to invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const addResult = addLine(result.value, { sku: 'DES-HOUR', qty: 3 });

  assert(addResult.ok);
  assert.equal(addResult.value.lines.length, 2);
  assert.equal(addResult.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(addResult.value.lines[1].sku, 'DES-HOUR');
  assert.equal(addResult.value.lines[1].qty, 3);
  assert.equal(addResult.value.lines[1].name, 'Design work (hour)');
  assert.equal(addResult.value.lines[1].unitPrice, 8500);
});

test('addLine: increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const addResult = addLine(result.value, { sku: 'DEV-HOUR', qty: 3 });

  assert(addResult.ok);
  assert.equal(addResult.value.lines.length, 1);
  assert.equal(addResult.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(addResult.value.lines[0].qty, 8);
});

test('addLine: preserves other properties', () => {
  const result = createInvoice({
